<?php
declare(strict_types=1); namespace Theobroma\OneC\Import;
final class CatalogImportParser {/** @return list<CatalogUpdate> */public function parse(string$xml,int$limit=10485760):array{$root=SafeXml::load($xml,$limit);$nodes=$root->xpath('//*[local-name()="Предложение"]')?:[];$out=[];foreach($nodes as$n){$rawId=SafeXml::value($n,'Ид');$id=explode('#',$rawId,2)[0];$ids=array_filter(['1c_guid'=>$id,'1c_article'=>SafeXml::value($n,'Артикул'),'ean'=>SafeXml::value($n,'Штрихкод')],fn($v)=>$v!=='');if(!$ids)continue;$prices=$n->xpath('./*[local-name()="Цены"]/*[local-name()="Цена"]/*[local-name()="ЦенаЗаЕдиницу"]')?:[];$price=count($prices)===1&&is_numeric((string)$prices[0])?number_format((float)$prices[0],2,'.',''):null;$direct=SafeXml::value($n,'Количество');$stock=$direct!==''&&is_numeric($direct)?(float)$direct:null;$warehouses=$n->xpath('./*[local-name()="Склад"]')?:[];if($warehouses){$stock=0.0;foreach($warehouses as$w){$a=$w->attributes();$q=(string)($a['КоличествоНаСкладе']??'');if(is_numeric($q))$stock+=(float)$q;}}$out[]=new CatalogUpdate($ids,$price,$stock);}return$out;}}
